logger.message:
#[%dw 2.0
output application/json
---
{
	"message": "Retrived check list lines that need to be reprocessed from salesforce"
}]

#[%dw 2.0
output application/json
---
{
    "message": "No checklist lines records found in salesforce for reprocessing"
}]

#[%dw 2.0
output application/json
---
{
	"message": "Completed Reprocessing of all the records"
}]

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	query: p('salesforce.ContentDocumentLinkQuery'),
	"parameters": {
		Id: "('" ++ ((payload map ((item, index) -> item.checklistLineId) distinctBy ((item, index) -> item)) joinBy  "','") ++ "')"
	}
}

logger.message:
#[%dw 2.0
output application/json
---
{
	"message": "Retrived content document data for reprocessing records from salesforce"
}]

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	"query": p('salesforce.claimQuery'),
	"parameters": {
		Id: "('" ++ ((vars.repairOrder map ((item, index) -> item.repairOrderId) distinctBy ((item, index) -> item)) joinBy  "','") ++ "')"
	}
}

logger.message:
#[%dw 2.0
output application/json
---
{
	"message": "Retrived claim information from salesforce"
}]

#[%dw 2.0
output application/json
---
{
    "message": "No claims records found in salesforce for reprocessing"
}]

#[%dw 2.0
output application/json
---
{
    "message": "No content document data records found in salesforce for reprocessing"
}]
